-- ---------------------------------------------------------------------------
-- (C) 21 index P0 (nguồn: add_indexes_p0.sql, nguyên tên index/cột)
--     Chạy sau khi bảng đã có (tức sau md_yzs.sql). Procedure kiểm tra
--     trước khi tạo nên chạy lại an toàn.
-- ---------------------------------------------------------------------------
DELIMITER $$
DROP PROCEDURE IF EXISTS add_index_if_missing $$
CREATE PROCEDURE add_index_if_missing(
  IN p_table VARCHAR(64),
  IN p_index VARCHAR(64),
  IN p_cols  VARCHAR(255)
)
BEGIN
  DECLARE v_cnt INT DEFAULT 0;
  SELECT COUNT(*) INTO v_cnt
    FROM information_schema.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME = p_table
     AND INDEX_NAME = p_index;
  IF v_cnt = 0 THEN
    SET @ddl = CONCAT('ALTER TABLE `', p_table, '` ADD INDEX `', p_index, '` (', p_cols, ')');
    PREPARE stmt FROM @ddl;
    EXECUTE stmt;
    DEALLOCATE PREPARE stmt;
  END IF;
END $$
DELIMITER ;
-- Bảng thuốc: thuê bao + mã + tên
CALL add_index_if_missing('drug', 'idx_drug_company', '`company_id`');
CALL add_index_if_missing('drug', 'idx_drug_code', '`company_id`, `code`');
CALL add_index_if_missing('drug', 'idx_drug_goods_name', '`company_id`, `goods_name`');
-- Bảng bệnh nhân: số điện thoại / số thẻ / thuê bao
CALL add_index_if_missing('patient', 'idx_patient_company', '`company_id`');
CALL add_index_if_missing('patient', 'idx_patient_phone', '`company_id`, `phone`');
CALL add_index_if_missing('patient', 'idx_patient_card', '`company_id`, `card`');
-- Bảng đăng ký khám
CALL add_index_if_missing('registration', 'idx_reg_company', '`company_id`');
CALL add_index_if_missing('registration', 'idx_reg_patient', '`patient_id`');
CALL add_index_if_missing('registration', 'idx_reg_status', '`company_id`, `status`');
-- Bảng thông tin đơn thuốc
CALL add_index_if_missing('recipel_info', 'idx_ri_registration', '`registration_id`');
CALL add_index_if_missing('recipel_info', 'idx_ri_company', '`company_id`');
-- Bảng kiểm soát tổng tồn kho
CALL add_index_if_missing('medicinal_stock_control', 'idx_msc_drug_stuff', '`drug_stuff_id`');
CALL add_index_if_missing('medicinal_stock_control', 'idx_msc_company', '`company_id`');
-- Bảng chi tiết tồn kho
CALL add_index_if_missing('medicinal_stock_record', 'idx_msr_drug_stuff', '`drug_stuff_id`');
-- Bảng tồn kho nhà cung cấp
CALL add_index_if_missing('supplier_stock', 'idx_ss_company', '`company_id`');
CALL add_index_if_missing('supplier_stock', 'idx_ss_drug', '`drug_id`');
-- Bảng quản lý nhiệm vụ + phản hồi
CALL add_index_if_missing('taskmanagement', 'idx_tm_company', '`company_id`');
CALL add_index_if_missing('taskmanagement', 'idx_tm_status', '`company_id`, `taskstatus`');
CALL add_index_if_missing('feedbacktable', 'idx_fb_task', '`taskmanagement_id`');
-- Bảng mẫu bệnh án
CALL add_index_if_missing('casehistorymbgl', 'idx_chmb_company', '`company_id`');
-- Bảng bài viết
CALL add_index_if_missing('article', 'idx_article_company', '`company_id`');
DROP PROCEDURE IF EXISTS add_index_if_missing;

SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------------
-- KIỂM CHỨNG SAU KHI CHẠY (chỉ đọc, không sửa dữ liệu):
--   Kỳ vọng trên DB vừa import md_yzs.sql + file này:
--     notice_send: bảng tồn tại; ureport_file: 7 dòng;
--     21 index dưới đây: mỗi tên xuất hiện đúng 1 lần trong
--     information_schema.STATISTICS.
-- ---------------------------------------------------------------------------
SELECT COUNT(*) AS ureport_file_rows FROM ureport_file;
SELECT COUNT(*) AS notice_send_tables FROM information_schema.tables
 WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'notice_send';
SELECT COUNT(DISTINCT INDEX_NAME) AS p0_index_count FROM information_schema.STATISTICS
 WHERE TABLE_SCHEMA = DATABASE() AND INDEX_NAME IN (
  'idx_drug_company','idx_drug_code','idx_drug_goods_name',
  'idx_patient_company','idx_patient_phone','idx_patient_card',
  'idx_reg_company','idx_reg_patient','idx_reg_status',
  'idx_ri_registration','idx_ri_company',
  'idx_msc_drug_stuff','idx_msc_company',
  'idx_msr_drug_stuff',
  'idx_ss_company','idx_ss_drug',
  'idx_tm_company','idx_tm_status','idx_fb_task',
  'idx_chmb_company','idx_article_company');

